using System.Text.Json;
using System.Text.Json.Serialization.Metadata;

// Set up options with the default reflection-based resolver
var options = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver()
};

// --- 1. Strongly-typed retrieval: GetTypeInfo<T>() returns JsonTypeInfo<T> ---
JsonTypeInfo<Person> personInfo = options.GetTypeInfo<Person>();
Console.WriteLine($"Got typed metadata for: {personInfo.Type.Name}");

// Use it to serialize
string json = JsonSerializer.Serialize(new Person("Alice", 30), personInfo);
Console.WriteLine($"Serialized: {json}");

// --- 2. Probe without throwing: TryGetTypeInfo ---
// This type IS resolvable (reflection resolver handles anything)
if (options.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? info))
{
    Console.WriteLine($"TryGetTypeInfo succeeded for Person (kind: {info!.Kind})");
}

// Now use an options instance with NO resolver — metadata won't be available
var emptyOptions = new JsonSerializerOptions
{
    TypeInfoResolver = null
};

if (emptyOptions.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? missing))
{
    Console.WriteLine("Unexpectedly found metadata!");
}
else
{
    Console.WriteLine("TryGetTypeInfo returned false — no metadata available (no throw!)");
}

// Simple record for the demo
public record Person(string Name, int Age);

